source='''from collections import Counter


def transform(grid):
    n = len(grid)
    zero_rows = [r for r, row in enumerate(grid) if all(v == 0 for v in row)]
    zero_cols = [c for c in range(n) if all(grid[r][c] == 0 for r in range(n))]
    intervals = []
    for positions in (zero_rows, zero_cols):
        intervals.extend(b - a for a, b in zip(positions, positions[1:]))
    if not intervals:
        raise ValueError("Could not locate tile gutters")
    period = Counter(intervals).most_common(1)[0][0]
    tile_size = period - 1
    starts = list(range(0, n, period))
    starts = [s for s in starts if s + tile_size <= n]

    # The repeated tile itself is also the occupancy mask for the larger tile grid.
    candidates = []
    for r0 in starts:
        for c0 in starts:
            tile = tuple(tuple(grid[r0 + r][c0 + c] for c in range(tile_size))
                         for r in range(tile_size))
            if any(v == 2 for row in tile for v in row) and not any(
                    v == 3 for row in tile for v in row):
                candidates.append(tile)
    if not candidates:
        raise ValueError("Could not find an unmasked tile")
    shape = Counter(candidates).most_common(1)[0][0]

    out = [[0] * n for _ in range(n)]
    for i, r0 in enumerate(starts):
        for j, c0 in enumerate(starts):
            if shape[i][j] != 2:
                continue
            for r in range(tile_size):
                for c in range(tile_size):
                    out[r0 + r][c0 + c] = shape[r][c]
            # Mark the cell indexed by this tile's position in the motif copy.
            if shape[i][j] == 2:
                out[r0 + i][c0 + j] = 8
    return out
'''
